// ===== 解析VIX指數 =====
const raw = $json.data;
if (!raw || typeof raw !== 'string') {
  throw new Error('[解析VIX指數] CBOE 回傳格式不是預期的字串，請檢查 API 是否變動');
}

const lines = raw.trim().split('\n').filter(Boolean);
if (lines.length < 2) {
  throw new Error('[解析VIX指數] CSV 內容異常，行數不足');
}

const lastLine = lines[lines.length - 1];
const cols = lastLine.split(',');
if (cols.length < 5) {
  throw new Error(`[解析VIX指數] 最後一行欄位數異常：${lastLine}`);
}
const [dateStr, , , , closeStr] = cols;

const dateParts = dateStr.split('/');
if (dateParts.length !== 3) {
  throw new Error(`[解析VIX指數] 日期格式非預期的 MM/DD/YYYY：${dateStr}`);
}
const [mm, dd, yyyy] = dateParts;
const vixDate = `${yyyy}-${mm.padStart(2, '0')}-${dd.padStart(2, '0')}`;
const vixClose = Number(closeStr);

if (!Number.isFinite(vixClose) || vixClose <= 0) {
  throw new Error(`[解析VIX指數] 收盤價解析失敗：${closeStr}`);
}

// 防呆：資料太舊代表來源可能沒更新，報告不該用過期的 VIX 判斷市場情緒
const staleDays = Math.floor((Date.now() - new Date(vixDate + 'T00:00:00Z').getTime()) / 86400000);
if (staleDays > 5) {
  console.log(`[解析VIX指數] 警告：最新資料是 ${vixDate}，距今 ${staleDays} 天，可能來源沒更新`);
}

console.log(`[解析VIX指數] ${vixDate} 收盤 ${vixClose}`);

return [{
  json: {
    ...$('整理歷史紀錄文字').first().json,
    vixClose,
    vixDate,
  },
}];
